<?php
namespace Ishep\Http\Controllers;use Throwable;use DomainException;use Ishep\Bootstrap\Application as App;use Ishep\Http\{Request,Response};
final class FinanceController
{private function app():App{return App::instance();}private function uid():int{return(int)$this->app()->session()->get('user_id');}private function staff():bool{return(bool)array_intersect($this->app()->roles()->roles($this->uid()),['finance','super_user']);}private function fail(Throwable $e,string $to):Response{$this->app()->session()->flash('errors',['finance'=>[$e instanceof DomainException?$e->getMessage():'The financial action could not be completed safely.']]);return Response::redirect(url($to));}
public function membership(Request $r):Response{return$this->app()->render('finance/membership',['membership'=>$this->app()->finance()->membershipForUser($this->uid()),'invoices'=>$this->app()->finance()->invoices($this->uid())]);}public function memberInvoices(Request $r):Response{return$this->app()->render('finance/invoices',['invoices'=>$this->app()->finance()->invoices($this->uid()),'staff'=>false]);}public function staffInvoices(Request $r):Response{return$this->app()->render('finance/invoices',['invoices'=>$this->app()->finance()->invoices(null,trim((string)($r->query['status']??''))?:null),'staff'=>true]);}public function invoice(Request $r):Response{$i=$this->app()->finance()->invoice((string)$r->get('reference'),$this->staff()?null:$this->uid());return$i?$this->app()->render('finance/invoice',['invoice'=>$i,'items'=>$this->app()->finance()->invoiceItems((int)$i['id']),'staff'=>$this->staff()]):$this->app()->render('errors/404',[],404);}public function fees(Request $r):Response{return$this->app()->render('finance/fees',['fees'=>$this->app()->finance()->fees(),'types'=>$this->app()->memberships()->active(),'create'=>str_ends_with($r->path,'/create')]);}
public function createFee(Request $r):Response{try{$ref=$this->app()->financeService()->createFee($this->uid(),$r->input,$r->ip());$this->app()->session()->flash('status','Fee schedule '.$ref.' created.');return Response::redirect(url('/finance/fees'));}catch(Throwable $e){return$this->fail($e,'/finance/fees/create');}}public function deactivateFee(Request $r):Response{try{$this->app()->financeService()->deactivateFee($this->uid(),(string)$r->get('reference'),$r->ip());$this->app()->session()->flash('status','Fee schedule deactivated; historical invoices were not changed.');return Response::redirect(url('/finance/fees'));}catch(Throwable $e){return$this->fail($e,'/finance/fees');}}
public function payments(Request $r):Response{return$this->app()->render('finance/payments',['payments'=>$this->app()->finance()->payments($this->staff()?null:$this->uid()),'invoices'=>$this->staff()?$this->app()->finance()->invoices():[],'staff'=>$this->staff(),'create'=>str_ends_with($r->path,'/create')]);}public function recordPayment(Request $r):Response{try{$ref=$this->app()->financeService()->recordPayment($this->uid(),$r->input,$r->ip());$this->app()->session()->flash('status','Manual payment '.$ref.' recorded.');return Response::redirect(url('/finance/payments/'.$ref.'/receipt'));}catch(Throwable $e){return$this->fail($e,'/finance/payments/create');}}public function receipt(Request $r):Response{$p=$this->app()->finance()->payment((string)$r->get('reference'),$this->staff()?null:$this->uid());return$p?$this->app()->render('finance/receipt',['payment'=>$p,'staff'=>$this->staff()]):$this->app()->render('errors/404',[],404);}public function reverse(Request $r):Response{try{$new=$this->app()->financeService()->reversePayment($this->uid(),(string)$r->get('reference'),(string)($r->input['reason']??''),$r->ip());$this->app()->session()->flash('status','Reversal '.$new.' recorded; the original remains in history.');return Response::redirect(url('/finance/payments'));}catch(Throwable $e){return$this->fail($e,'/finance/payments');}}
public function refunds(Request $r):Response{return$this->app()->render('finance/refunds',['requests'=>$this->app()->finance()->refundRequests($this->staff()?null:$this->uid()),'payments'=>$this->staff()?[]:$this->app()->finance()->payments($this->uid()),'staff'=>$this->staff()]);}public function requestRefund(Request $r):Response{try{$ref=$this->app()->financeService()->requestRefund($this->uid(),(string)($r->input['payment_reference']??''),(string)($r->input['amount']??''),(string)($r->input['reason']??''),$r->ip());$this->app()->session()->flash('status','Refund request '.$ref.' submitted.');return Response::redirect(url('/finance/refunds'));}catch(Throwable $e){return$this->fail($e,'/finance/refunds');}}public function decideRefund(Request $r):Response{try{$this->app()->financeService()->decideRefund($this->uid(),(string)$r->get('reference'),(string)$r->get('action'),(string)($r->input['decision_reason']??''),$r->ip());$this->app()->session()->flash('status','Refund decision recorded.');return Response::redirect(url('/finance/refunds'));}catch(Throwable $e){return$this->fail($e,'/finance/refunds');}}public function processRefund(Request $r):Response{try{$ref=$this->app()->financeService()->processRefund($this->uid(),(string)$r->get('reference'),(string)($r->input['method']??''),(string)($r->input['manual_reference']??''),$r->ip());$this->app()->session()->flash('status','Manual refund '.$ref.' recorded.');return Response::redirect(url('/finance/refunds'));}catch(Throwable $e){return$this->fail($e,'/finance/refunds');}}public function dashboard(Request $r):Response{return$this->app()->render('finance/dashboard',['counts'=>$this->app()->finance()->counts(),'payments'=>$this->app()->finance()->payments()]);}}
